CREATE TABLE public.hiring_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), full_name text NOT NULL CHECK(length(full_name) BETWEEN 1 AND 100), phone text NOT NULL DEFAULT '' CHECK(length(phone)<=30), service_areas text NOT NULL CHECK(length(service_areas) BETWEEN 1 AND 500), experience text NOT NULL CHECK(length(experience) BETWEEN 1 AND 3000), availability text NOT NULL CHECK(length(availability) BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','reviewing','hired','declined')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.hiring_applications TO authenticated; GRANT ALL ON public.hiring_applications TO service_role;
ALTER TABLE public.hiring_applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own applications and admin review" ON public.hiring_applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Submit own application" ON public.hiring_applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='submitted');
CREATE FUNCTION public.review_application(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE applicant uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF _status NOT IN ('reviewing','hired','declined') THEN RAISE EXCEPTION 'Invalid review status'; END IF; SELECT user_id INTO applicant FROM public.hiring_applications WHERE id=_id FOR UPDATE; IF applicant IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF; UPDATE public.hiring_applications SET status=_status WHERE id=_id; IF _status='hired' THEN INSERT INTO public.user_roles(user_id,role) VALUES(applicant,'cleaner') ON CONFLICT(user_id,role) DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_application(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_application(uuid,text) TO authenticated;
CREATE TABLE public.message_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('staff','booking')), cleaner_id uuid NOT NULL REFERENCES public.profiles(id), booking_id uuid REFERENCES public.bookings(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK((kind='staff' AND booking_id IS NULL) OR (kind='booking' AND booking_id IS NOT NULL)));
CREATE UNIQUE INDEX staff_thread_per_cleaner ON public.message_threads(cleaner_id) WHERE kind='staff'; CREATE UNIQUE INDEX thread_per_booking ON public.message_threads(booking_id) WHERE kind='booking';
GRANT SELECT ON public.message_threads TO authenticated; GRANT ALL ON public.message_threads TO service_role;
ALTER TABLE public.message_threads ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_thread(_thread uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.message_threads t WHERE t.id=_thread AND (public.has_role(auth.uid(),'admin') OR (t.kind='staff' AND t.cleaner_id=auth.uid() AND public.has_role(auth.uid(),'cleaner')) OR (t.kind='booking' AND EXISTS(SELECT 1 FROM public.bookings b WHERE b.id=t.booking_id AND ((b.cleaner_id=auth.uid() AND public.has_role(auth.uid(),'cleaner')) OR b.user_id=auth.uid() OR (lower(b.email)=lower(auth.jwt()->>'email') AND (auth.jwt()->>'email_verified')::boolean IS DISTINCT FROM false)))))); $$;
REVOKE ALL ON FUNCTION public.can_read_thread(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_read_thread(uuid) TO authenticated;
CREATE POLICY "Participants read threads" ON public.message_threads FOR SELECT TO authenticated USING(public.can_read_thread(id));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.message_threads(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id), sender_name text NOT NULL, body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 3000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read messages" ON public.messages FOR SELECT TO authenticated USING(public.can_read_thread(thread_id));
CREATE INDEX messages_thread_date ON public.messages(thread_id,created_at);
CREATE FUNCTION public.open_message_thread(_cleaner uuid DEFAULT NULL,_booking uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; c uuid; b public.bookings; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _booking IS NOT NULL THEN SELECT * INTO b FROM public.bookings WHERE id=_booking; IF b.id IS NULL OR b.cleaner_id IS NULL THEN RAISE EXCEPTION 'A cleaner must be assigned first'; END IF; IF NOT (public.has_role(auth.uid(),'admin') OR (b.cleaner_id=auth.uid() AND public.has_role(auth.uid(),'cleaner')) OR b.user_id=auth.uid() OR (lower(b.email)=lower(auth.jwt()->>'email') AND (auth.jwt()->>'email_verified')::boolean IS DISTINCT FROM false)) THEN RAISE EXCEPTION 'Booking access required'; END IF; INSERT INTO public.message_threads(kind,cleaner_id,booking_id) VALUES('booking',b.cleaner_id,b.id) ON CONFLICT(booking_id) WHERE kind='booking' DO UPDATE SET cleaner_id=excluded.cleaner_id RETURNING id INTO t; ELSE c:=coalesce(_cleaner,auth.uid()); IF NOT public.has_role(c,'cleaner') OR NOT (public.has_role(auth.uid(),'admin') OR c=auth.uid()) THEN RAISE EXCEPTION 'Cleaner or admin access required'; END IF; INSERT INTO public.message_threads(kind,cleaner_id) VALUES('staff',c) ON CONFLICT(cleaner_id) WHERE kind='staff' DO UPDATE SET cleaner_id=excluded.cleaner_id RETURNING id INTO t; END IF; RETURN t; END $$;
REVOKE ALL ON FUNCTION public.open_message_thread(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_message_thread(uuid,uuid) TO authenticated;
CREATE FUNCTION public.send_thread_message(_thread uuid,_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text; BEGIN IF NOT public.can_read_thread(_thread) THEN RAISE EXCEPTION 'Conversation access required'; END IF; IF length(trim(_body)) NOT BETWEEN 1 AND 3000 THEN RAISE EXCEPTION 'Message must be 1–3000 characters'; END IF; SELECT coalesce(nullif(full_name,''),'Account member') INTO n FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.messages(thread_id,sender_id,sender_name,body) VALUES(_thread,auth.uid(),n,trim(_body)); END $$;
REVOKE ALL ON FUNCTION public.send_thread_message(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.send_thread_message(uuid,text) TO authenticated;
CREATE TABLE public.housekeeper_portfolios (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 100), headline text NOT NULL DEFAULT '' CHECK(length(headline)<=180), bio text NOT NULL DEFAULT '' CHECK(length(bio)<=3000), service_areas text NOT NULL DEFAULT '' CHECK(length(service_areas)<=500), portrait_path text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(portrait_path='' OR portrait_path LIKE user_id::text || '/%'));
GRANT SELECT ON public.housekeeper_portfolios TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.housekeeper_portfolios TO authenticated; GRANT ALL ON public.housekeeper_portfolios TO service_role;
ALTER TABLE public.housekeeper_portfolios ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published portfolios" ON public.housekeeper_portfolios FOR SELECT TO anon,authenticated USING(published AND public.has_role(user_id,'cleaner'));
CREATE POLICY "Own portfolio" ON public.housekeeper_portfolios FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'cleaner')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'cleaner'));
CREATE TABLE public.housekeeper_gallery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.housekeeper_portfolios(user_id) ON DELETE CASCADE, caption text NOT NULL DEFAULT '' CHECK(length(caption)<=200), before_path text NOT NULL, after_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(before_path LIKE user_id::text || '/%' AND after_path LIKE user_id::text || '/%'));
GRANT SELECT ON public.housekeeper_gallery TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.housekeeper_gallery TO authenticated; GRANT ALL ON public.housekeeper_gallery TO service_role;
ALTER TABLE public.housekeeper_gallery ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public gallery" ON public.housekeeper_gallery FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.housekeeper_portfolios p WHERE p.user_id=housekeeper_gallery.user_id AND p.published AND public.has_role(p.user_id,'cleaner')));
CREATE POLICY "Own gallery" ON public.housekeeper_gallery FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'cleaner')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'cleaner'));